import { day } from './dates'
import type { Attr, Day, Fact, Value } from './types'

/**
 * System time is monotonic: a new fact is recorded at the current clock, never
 * before it. Valid time is unconstrained in both directions. The asymmetry is
 * the semantics, not a simplification — valid time is a claim about the world
 * and may be revised, system time is the record of what we did and may not.
 */
export class MonotonicSystemTimeError extends Error {
  constructor(attempted: Day, latest: Day) {
    super(`cannot record at system time ${attempted}: log already reaches ${latest}`)
    this.name = 'MonotonicSystemTimeError'
  }
}

export function latestSystemTime(log: readonly Fact[]): Day {
  return log.reduce((max, f) => (f.systemTime > max ? f.systemTime : max), 0)
}

let counter = 0
export function nextFactId(): string {
  counter += 1
  return `f${counter}`
}

export function makeFact(
  attr: Attr, value: Value, validFrom: Day, systemTime: Day, id = nextFactId(),
): Fact {
  return { id, attr, value, validFrom, systemTime }
}

/** Append a fact, enforcing the monotonic system clock. */
export function append(log: readonly Fact[], fact: Fact): Fact[] {
  const latest = latestSystemTime(log)
  if (fact.systemTime < latest) throw new MonotonicSystemTimeError(fact.systemTime, latest)
  return [...log, fact]
}

/**
 * The scenario from Chronoscope.md, on a calendar.
 *
 * The fourth fact is the whole demo: recorded 10 June, valid from 1 March — after
 * the 1 April manager change was already written. It is also what breaks the
 * uninvalidated snapshot strategy, because the snapshot taken at 1 April carries
 * salary = 60,000 (only the manager changed that day) and nothing goes back to
 * correct it.
 */
export const SCENARIO: Fact[] = [
  makeFact('salary', 60_000, day(2026, 1, 15), day(2026, 1, 15), 'hire-salary'),
  makeFact('manager', 'Jim', day(2026, 1, 15), day(2026, 1, 15), 'hire-manager'),
  makeFact('manager', 'Rob', day(2026, 4, 1), day(2026, 4, 1), 'reorg'),
  makeFact('salary', 72_000, day(2026, 3, 1), day(2026, 6, 10), 'backdated-raise'),
]

/** Window the interface renders. Both axes share it, so the plane is square. */
export const HORIZON = { start: day(2026, 1, 1), end: day(2026, 9, 1) }

import { ATTRS } from './types'
import type { Attr, Day, EntityState, Fact, Value } from './types'

/**
 * The oracle: deliberately slow, obviously correct, and the only thing any
 * strategy is judged against.
 *
 * Keep what we had recorded by `system`, and what had become true by `valid`.
 * The winner is the greatest validFrom; ties — a correction at an existing
 * valid time — go to the greatest systemTime.
 */
export function referenceQuery(
  log: readonly Fact[], attr: Attr, valid: Day, system: Day,
): Value | undefined {
  let best: Fact | undefined
  for (const f of log) {
    if (f.attr !== attr) continue
    if (f.systemTime > system) continue
    if (f.validFrom > valid) continue
    if (
      best === undefined ||
      f.validFrom > best.validFrom ||
      (f.validFrom === best.validFrom && f.systemTime > best.systemTime)
    ) {
      best = f
    }
  }
  return best?.value
}

export function referenceState(
  log: readonly Fact[], valid: Day, system: Day,
): EntityState {
  const state: EntityState = {}
  for (const attr of ATTRS) {
    const v = referenceQuery(log, attr, valid, system)
    if (v !== undefined) state[attr] = v
  }
  return state
}

import type { Attr, Day, Fact, Value } from '../types'

/** Work done by applying one fact. Observed, not modelled. */
export type OpCounts = {
  /** new records appended */
  written: number
  /** existing records closed or rewritten in place */
  rewritten: number
  /** derived state dropped and rebuilt */
  invalidated: number
}

export const NO_OPS: OpCounts = { written: 0, rewritten: 0, invalidated: 0 }

export function addOps(a: OpCounts, b: OpCounts): OpCounts {
  return {
    written: a.written + b.written,
    rewritten: a.rewritten + b.rewritten,
    invalidated: a.invalidated + b.invalidated,
  }
}

export type Config = {
  /** Grid spacing in days for strategies that snapshot on a schedule. */
  snapshotInterval: number
}

export const DEFAULT_CONFIG: Config = { snapshotInterval: 30 }

export type Applied<S> = { state: S; ops: OpCounts }

/**
 * A representation of bitemporal history.
 *
 * `materialize` is deliberately absent: it is always a fold of `apply` over
 * `empty`, so the batch path and the incremental path cannot drift, and the
 * operation counts shown in the interface are the same ones a real write would
 * have paid.
 */
export interface Strategy<S = unknown> {
  key: string
  name: string
  blurb: string
  /** false for the deliberately incorrect strategy. */
  correct: boolean
  empty(cfg: Config): S
  apply(state: S, fact: Fact, cfg: Config): Applied<S>
  query(state: S, attr: Attr, valid: Day, system: Day): Value | undefined
  /** Records the read had to touch. Observation for the strategy row, not a projection. */
  readCost(state: S, attr: Attr, valid: Day, system: Day): number
  /** Records currently stored, for the duplicated-state comparison. */
  size(state: S): number
}

export function materialize<S>(
  strategy: Strategy<S>, log: readonly Fact[], cfg: Config,
): { state: S; ops: OpCounts } {
  let state = strategy.empty(cfg)
  let ops = NO_OPS
  for (const fact of log) {
    const applied = strategy.apply(state, fact, cfg)
    state = applied.state
    ops = addOps(ops, applied.ops)
  }
  return { state, ops }
}

import type { Attr, Day, Fact, Value } from '../types'
import type { Applied, Config, Strategy } from './index'

export type DeltaState = { facts: Fact[] }

/**
 * Store the facts and nothing else. The cheapest possible write and the most
 * expensive possible read: every query replays the whole log. Corrections are
 * free to record and cost nothing extra to store — the price is paid forever
 * afterwards, on every read.
 */
export const deltas: Strategy<DeltaState> = {
  key: 'deltas',
  name: 'Deltas',
  blurb: 'Append-only log of facts. Reads replay.',
  correct: true,

  empty: () => ({ facts: [] }),

  apply(state: DeltaState, fact: Fact, _cfg: Config): Applied<DeltaState> {
    return {
      state: { facts: [...state.facts, fact] },
      ops: { written: 1, rewritten: 0, invalidated: 0 },
    }
  },

  query(state: DeltaState, attr: Attr, valid: Day, system: Day): Value | undefined {
    let best: Fact | undefined
    for (const f of state.facts) {
      if (f.attr !== attr || f.systemTime > system || f.validFrom > valid) continue
      if (
        best === undefined ||
        f.validFrom > best.validFrom ||
        (f.validFrom === best.validFrom && f.systemTime > best.systemTime)
      ) best = f
    }
    return best?.value
  },

  readCost: (state: DeltaState) => state.facts.length,
  size: (state: DeltaState) => state.facts.length,
}

import { INF } from '../types'
import type { Attr, Day, Fact, Value } from '../types'
import type { Applied, Config, Strategy } from './index'

/**
 * A row is a rectangle on the bitemporal plane: a value that held over a range
 * of valid time, believed over a range of system time. Both ends are exclusive,
 * INF meaning still open.
 */
export type Interval = {
  id: string
  attr: Attr
  value: Value
  validFrom: Day
  validTo: Day
  systemFrom: Day
  systemTo: Day
}

export type IntervalState = { rows: Interval[]; seq: number }

const isOpen = (r: Interval) => r.systemTo === INF

/**
 * Validity intervals — the classic bitemporal table.
 *
 * Reads are a direct lookup: find the rectangle containing the coordinate. The
 * price is on write. A retroactive fact does not append, it *rewrites*: every
 * open row it overlaps is closed in system time and reopened with adjusted
 * valid bounds. Nothing is ever mutated in place, so the system-time axis stays
 * an audit trail, but one fact can touch many rows.
 *
 * The subtlety worth reading: the new fact does not run to infinity. It holds
 * only until the next already-known fact supersedes it, so its valid range is
 * clipped at the nearest greater validFrom. Skipping that clip is the classic
 * way to make a retroactive insert silently swallow every later change.
 */
export const intervals: Strategy<IntervalState> = {
  key: 'intervals',
  name: 'Intervals',
  blurb: 'Bitemporal rectangles. Direct reads, rewriting writes.',
  correct: true,

  empty: () => ({ rows: [], seq: 0 }),

  apply(state: IntervalState, fact: Fact, _cfg: Config): Applied<IntervalState> {
    const { attr, value, validFrom: v, systemTime: t } = fact
    let seq = state.seq
    const id = () => `${fact.id}-${++seq}`

    const open = state.rows.filter((r) => r.attr === attr && isOpen(r))

    // The new fact holds until the next thing we already know about.
    let nextValid = INF
    for (const r of open) {
      if (r.validFrom > v && r.validFrom < nextValid) nextValid = r.validFrom
    }

    const rows: Interval[] = []
    let written = 0
    let rewritten = 0

    for (const r of state.rows) {
      const untouched =
        r.attr !== attr || !isOpen(r) || r.validTo <= v || r.validFrom >= nextValid
      if (untouched) {
        rows.push(r)
        continue
      }

      // Close in system time rather than mutating. A zero-width system range can
      // never be read back, so it is dropped rather than stored as noise.
      if (r.systemFrom < t) {
        rows.push({ ...r, systemTo: t })
        rewritten += 1
      } else {
        rewritten += 1
      }

      // Reopen whatever of this row survives on either side of the new fact.
      if (r.validFrom < v) {
        rows.push({ ...r, id: id(), validTo: v, systemFrom: t, systemTo: INF })
        written += 1
      }
      if (r.validTo > nextValid) {
        rows.push({ ...r, id: id(), validFrom: nextValid, systemFrom: t, systemTo: INF })
        written += 1
      }
    }

    rows.push({
      id: id(), attr, value,
      validFrom: v, validTo: nextValid,
      systemFrom: t, systemTo: INF,
    })
    written += 1

    return { state: { rows, seq }, ops: { written, rewritten, invalidated: 0 } }
  },

  query(state: IntervalState, attr: Attr, valid: Day, system: Day): Value | undefined {
    for (const r of state.rows) {
      if (r.attr !== attr) continue
      if (valid < r.validFrom || valid >= r.validTo) continue
      if (system < r.systemFrom || system >= r.systemTo) continue
      return r.value
    }
    return undefined
  },

  readCost: (state: IntervalState, attr: Attr) =>
    state.rows.filter((r) => r.attr === attr).length,
  size: (state: IntervalState) => state.rows.length,
}

import { referenceState } from '../reference'
import { INF } from '../types'
import type { Attr, Day, EntityState, Fact, Value } from '../types'
import type { Applied, Config, Strategy } from './index'

/**
 * A snapshot is itself bitemporal: a full-state view at one valid-time point,
 * believed over a range of system time. Retiring one closes it rather than
 * mutating it, same as intervals.ts, so past beliefs stay queryable.
 */
export type Snapshot = {
  id: string
  validAt: Day
  state: EntityState
  systemFrom: Day
  systemTo: Day
}

export type SnapshotState = { log: Fact[]; snapshots: Snapshot[]; seq: number }

/** Greatest validAt at or before `valid`, among snapshots live at `system`. */
export function liveSnapshot(
  snaps: readonly Snapshot[], valid: Day, system: Day,
): Snapshot | undefined {
  let best: Snapshot | undefined
  for (const s of snaps) {
    if (system < s.systemFrom || system >= s.systemTo) continue
    if (s.validAt > valid) continue
    if (best === undefined || s.validAt > best.validAt) best = s
  }
  return best
}

/**
 * One full-state snapshot per distinct validFrom seen in the log. A read is a
 * direct lookup: find the live snapshot with the greatest validAt <= valid and
 * you are done — no replay, ever. The cost moves entirely to the write. Every
 * snapshot is a cached projection of state, so a retroactive fact — one whose
 * validFrom lands before points we already snapshotted — must close and rebuild
 * all of them, because what they say just changed. Points before the fact's
 * validFrom are left alone: nothing that already happened can be altered by
 * something recorded to hold from a later point onward.
 */
export const snapshots: Strategy<SnapshotState> = {
  key: 'snapshots',
  name: 'Snapshots',
  blurb: 'One full-state snapshot per valid-time point seen. Direct reads, rebuilding writes.',
  correct: true,

  empty: () => ({ log: [], snapshots: [], seq: 0 }),

  apply(state: SnapshotState, fact: Fact, _cfg: Config): Applied<SnapshotState> {
    const { validFrom: v, systemTime: t } = fact
    const log = [...state.log, fact]
    let seq = state.seq
    const nextId = () => `${fact.id}-${++seq}`

    let invalidated = 0
    const kept: Snapshot[] = []
    for (const s of state.snapshots) {
      const affected = s.systemTo === INF && s.validAt >= v
      if (!affected) { kept.push(s); continue }
      invalidated += 1
      // A snapshot opened and closed at the same instant can never be read
      // back, so it is dropped rather than stored as noise (see intervals.ts).
      if (s.systemFrom < t) kept.push({ ...s, systemTo: t })
    }

    const points = [...new Set(log.map((f) => f.validFrom))].filter((p) => p >= v)
    let written = 0
    for (const p of points) {
      kept.push({
        id: nextId(), validAt: p, state: referenceState(log, p, t),
        systemFrom: t, systemTo: INF,
      })
      written += 1
    }

    return { state: { log, snapshots: kept, seq }, ops: { written, rewritten: 0, invalidated } }
  },

  query(state: SnapshotState, attr: Attr, valid: Day, system: Day): Value | undefined {
    return liveSnapshot(state.snapshots, valid, system)?.state[attr]
  },

  readCost: (state: SnapshotState, _attr: Attr, valid: Day, system: Day) =>
    liveSnapshot(state.snapshots, valid, system) === undefined ? 0 : 1,

  size: (state: SnapshotState) => state.snapshots.length,
}

import { HORIZON } from '../log'
import { referenceState } from '../reference'
import { INF } from '../types'
import type { Attr, Day, Fact, Value } from '../types'
import type { Applied, Config, Strategy } from './index'
import { liveSnapshot } from './snapshots'
import type { Snapshot } from './snapshots'

export type HybridState = { log: Fact[]; snapshots: Snapshot[]; seq: number }

function gridPoints(cfg: Config): Day[] {
  const points: Day[] = []
  for (let p = HORIZON.start; p <= HORIZON.end; p += cfg.snapshotInterval) points.push(p)
  return points
}

/** Facts that must be replayed on top of a snapshot at `lower`, in apply order. */
function replay(
  log: readonly Fact[], attr: Attr, lower: Day, valid: Day, system: Day,
): Fact[] {
  return log
    .filter((f) => f.attr === attr && f.systemTime <= system && f.validFrom > lower && f.validFrom <= valid)
    .sort((a, b) => a.validFrom - b.validFrom || a.systemTime - b.systemTime)
}

/**
 * Snapshots.ts with the grid fixed instead of data-driven: one snapshot every
 * cfg.snapshotInterval days across the horizon, plus the full log. Fewer cached
 * points, so a retroactive fact invalidates and rebuilds fewer records than
 * snapshots.ts does — cheaper storage, cheaper writes. The price comes back on
 * read as a bounded replay from the nearest grid point at or before `valid`,
 * instead of a direct hit.
 */
export const hybrid: Strategy<HybridState> = {
  key: 'hybrid',
  name: 'Hybrid',
  blurb: 'Snapshots on a fixed grid, plus the log. Bounded replay on read.',
  correct: true,

  empty: () => ({ log: [], snapshots: [], seq: 0 }),

  apply(state: HybridState, fact: Fact, cfg: Config): Applied<HybridState> {
    const { validFrom: v, systemTime: t } = fact
    const log = [...state.log, fact]
    let seq = state.seq
    const nextId = () => `${fact.id}-${++seq}`

    let invalidated = 0
    const kept: Snapshot[] = []
    for (const s of state.snapshots) {
      const affected = s.systemTo === INF && s.validAt >= v
      if (!affected) { kept.push(s); continue }
      invalidated += 1
      // A snapshot opened and closed at the same instant can never be read
      // back, so it is dropped rather than stored as noise (see intervals.ts).
      if (s.systemFrom < t) kept.push({ ...s, systemTo: t })
    }

    const points = gridPoints(cfg).filter((p) => p >= v)
    let written = 0
    for (const p of points) {
      kept.push({
        id: nextId(), validAt: p, state: referenceState(log, p, t),
        systemFrom: t, systemTo: INF,
      })
      written += 1
    }

    return { state: { log, snapshots: kept, seq }, ops: { written, rewritten: 0, invalidated } }
  },

  query(state: HybridState, attr: Attr, valid: Day, system: Day): Value | undefined {
    const snap = liveSnapshot(state.snapshots, valid, system)
    let value = snap?.state[attr]
    for (const f of replay(state.log, attr, snap?.validAt ?? -Infinity, valid, system)) {
      value = f.value
    }
    return value
  },

  readCost(state: HybridState, attr: Attr, valid: Day, system: Day): number {
    const snap = liveSnapshot(state.snapshots, valid, system)
    return 1 + replay(state.log, attr, snap?.validAt ?? -Infinity, valid, system).length
  },

  size: (state: HybridState) => state.snapshots.length,
}

import { referenceState } from '../reference'
import { INF } from '../types'
import type { Attr, Day, Fact, Value } from '../types'
import type { Applied, Config, Strategy } from './index'
import { liveSnapshot } from './snapshots'
import type { Snapshot } from './snapshots'

export type StaleSnapshotState = { log: Fact[]; snapshots: Snapshot[]; seq: number }

/**
 * snapshots.ts with the rebuild step removed. On apply it opens a snapshot at
 * the fact's own validFrom and nothing else — it never revisits snapshots
 * already sitting at later valid-time points, so a retroactive fact leaves
 * them holding whatever they held before.
 *
 * Concretely: the snapshot taken at 1 April carries salary = 60,000, because on
 * that day only the manager changed. The raise that should have applied from
 * 1 March is not recorded until 10 June, with a validFrom before that
 * snapshot's — and nothing goes back to rebuild it. So from the moment the
 * raise is recorded, every read at valid >= 1 April still returns the stale
 * 60,000 instead of 72,000, forever.
 */
export const snapshotStale: Strategy<StaleSnapshotState> = {
  key: 'snapshotStale',
  name: 'Snapshots, uninvalidated',
  blurb: 'Opens a snapshot at the new point only — later snapshots never get rebuilt.',
  correct: false,

  empty: () => ({ log: [], snapshots: [], seq: 0 }),

  apply(state: StaleSnapshotState, fact: Fact, _cfg: Config): Applied<StaleSnapshotState> {
    const { validFrom: v, systemTime: t } = fact
    const log = [...state.log, fact]
    let seq = state.seq
    const nextId = () => `${fact.id}-${++seq}`

    // Only the snapshot at exactly this valid point is touched — the bug.
    let invalidated = 0
    const kept: Snapshot[] = []
    for (const s of state.snapshots) {
      const affected = s.systemTo === INF && s.validAt === v
      if (!affected) { kept.push(s); continue }
      invalidated += 1
      if (s.systemFrom < t) kept.push({ ...s, systemTo: t })
    }

    kept.push({
      id: nextId(), validAt: v, state: referenceState(log, v, t),
      systemFrom: t, systemTo: INF,
    })

    return { state: { log, snapshots: kept, seq }, ops: { written: 1, rewritten: 0, invalidated } }
  },

  query(state: StaleSnapshotState, attr: Attr, valid: Day, system: Day): Value | undefined {
    return liveSnapshot(state.snapshots, valid, system)?.state[attr]
  },

  readCost: (state: StaleSnapshotState, _attr: Attr, valid: Day, system: Day) =>
    liveSnapshot(state.snapshots, valid, system) === undefined ? 0 : 1,

  size: (state: StaleSnapshotState) => state.snapshots.length,
}

import { useRef } from 'react'
import { formatDayLong } from '../core/dates'
import type { Day, Fact } from '../core/types'
import { invert, linear, monthTicks } from './scale'

type Props = {
  log: readonly Fact[]
  horizon: { start: Day; end: Day }
  validCursor: Day
  systemCursor: Day
  /** Nothing is known before it is recorded, so the system axis stops here. */
  clock: Day
  onValid: (d: Day) => void
  onSystem: (d: Day) => void
}

const W = 1000
const H = 208
const PAD = 16
const VALID_Y = 64
const SYSTEM_Y = 156
const GRAB = 30

function lean(f: Fact): 'retro' | 'future' | 'aligned' {
  if (f.systemTime > f.validFrom) return 'retro'
  if (f.systemTime < f.validFrom) return 'future'
  return 'aligned'
}

const STROKE = { retro: 'var(--retro)', future: 'var(--future)', aligned: 'var(--rule-strong)' }

/**
 * The two axes are the controls. Each carries its own cursor, dragged directly
 * on the timeline it belongs to, so there is no second copy of the same two
 * numbers as sliders elsewhere on the page.
 *
 * A fact sits at its valid time above and its system time below, joined by a
 * connector. Vertical when the two agree, leaning when they do not — which
 * shows the idea before any sentence about it does. Facts not yet recorded at
 * the system cursor are ghosted rather than hidden, so you can see what is
 * about to arrive.
 */
export function TwinTimelines({
  log, horizon, validCursor, systemCursor, clock, onValid, onSystem,
}: Props) {
  const svg = useRef<SVGSVGElement>(null)
  const x = linear([horizon.start, horizon.end], [PAD, W - PAD])
  const xBack = invert([horizon.start, horizon.end], [PAD, W - PAD])
  const ticks = monthTicks(horizon.start, horizon.end)

  const dayAt = (clientX: number): Day => {
    const box = svg.current!.getBoundingClientRect()
    return xBack(((clientX - box.left) / box.width) * W)
  }

  const drag = (set: (d: Day) => void) => (e: React.PointerEvent) => {
    e.currentTarget.setPointerCapture(e.pointerId)
    set(dayAt(e.clientX))
  }
  const move = (set: (d: Day) => void) => (e: React.PointerEvent) => {
    if (e.buttons !== 1) return
    set(dayAt(e.clientX))
  }

  return (
    <svg ref={svg} viewBox={`0 0 ${W} ${H}`} width="100%" role="group"
         aria-label="Facts against valid time and system time; drag either axis"
         style={{ touchAction: 'none', display: 'block' }}>
      {/* Nothing past the clock has happened yet, on either reading. */}
      <rect x={x(clock)} y={SYSTEM_Y - GRAB} width={Math.max(0, W - PAD - x(clock))}
            height={GRAB * 2} fill="var(--rule)" opacity={0.5} />

      {ticks.map((t) => (
        <g key={t}>
          <line x1={x(t)} x2={x(t)} y1={VALID_Y - 8} y2={VALID_Y + 8} stroke="var(--rule)" />
          <line x1={x(t)} x2={x(t)} y1={SYSTEM_Y - 8} y2={SYSTEM_Y + 8} stroke="var(--rule)" />
        </g>
      ))}

      {log.map((f) => {
        const kind = lean(f)
        const known = f.systemTime <= systemCursor
        return (
          <g key={f.id} opacity={known ? 1 : 0.2}>
            <line x1={x(f.validFrom)} y1={VALID_Y} x2={x(f.systemTime)} y2={SYSTEM_Y}
                  stroke={STROKE[kind]} strokeWidth={kind === 'aligned' ? 1 : 1.75}
                  strokeDasharray={known ? undefined : '3 3'} />
            <circle cx={x(f.validFrom)} cy={VALID_Y} r={4} fill={STROKE[kind]} />
            <circle cx={x(f.systemTime)} cy={SYSTEM_Y} r={4} fill={STROKE[kind]} />
          </g>
        )
      })}

      <Axis
        y={VALID_Y} label="valid time" question="when was it true?"
        cursor={validCursor} x={x} above
        onDown={drag(onValid)} onMove={move(onValid)}
      />
      <Axis
        y={SYSTEM_Y} label="system time" question="what did we know, and when?"
        cursor={systemCursor} x={x}
        onDown={drag(onSystem)} onMove={move(onSystem)}
      />
    </svg>
  )
}

function Axis({
  y, label, question, cursor, x, above, onDown, onMove,
}: {
  y: number; label: string; question: string; cursor: Day
  x: (d: Day) => number; above?: boolean
  onDown: (e: React.PointerEvent) => void
  onMove: (e: React.PointerEvent) => void
}) {
  const cx = x(cursor)
  const labelY = above ? y - 30 : y + 40
  const pillY = above ? y - 24 : y + 10
  return (
    <g>
      <line x1={PAD} x2={W - PAD} y1={y} y2={y} stroke="var(--rule-strong)" />

      <text x={PAD} y={labelY} fontSize={11.5} fontWeight={600} fill="var(--ink-soft)">
        {label}
        <tspan fill="var(--ink-faint)" fontWeight={400}> — {question}</tspan>
      </text>

      {/* One wide, invisible grab zone: the axis is the slider. */}
      <rect x={0} y={y - GRAB} width={W} height={GRAB * 2} fill="transparent"
            style={{ cursor: 'ew-resize' }} onPointerDown={onDown} onPointerMove={onMove} />

      <line x1={cx} x2={cx} y1={y - 16} y2={y + 16} stroke="var(--ink)" strokeWidth={1.5}
            pointerEvents="none" />
      <g pointerEvents="none">
        <rect x={cx - 46} y={pillY} width={92} height={15} rx={3} fill="var(--ink)" />
        <text x={cx} y={pillY + 11} fontSize={10} fill="#fff" textAnchor="middle">
          {formatDayLong(cursor)}
        </text>
      </g>
    </g>
  )
}

import { formatDayLong } from '../core/dates'
import { referenceQuery } from '../core/reference'
import { ATTRS } from '../core/types'
import type { Day, Fact, Value } from '../core/types'

export const show = (v: Value | undefined) =>
  v === undefined ? '—' : typeof v === 'number' ? v.toLocaleString('en-GB') : v

/**
 * Both attributes at once. A single fact only ever moves one of them, so
 * watching manager hold still while salary rewrites itself under a dragged
 * cursor is most of the lesson — and it is the contrast a second view would
 * have cost a whole panel to make.
 */
export function Readout({
  log, validCursor, systemCursor,
}: { log: readonly Fact[]; validCursor: Day; systemCursor: Day }) {
  return (
    <div className="panel" style={{ display: 'flex', gap: 44, alignItems: 'flex-end' }}>
      {ATTRS.map((attr) => (
        <div key={attr}>
          <div style={{ fontSize: 12, color: 'var(--ink-faint)' }}>{attr}</div>
          <div className="num" style={{ fontSize: 28, fontWeight: 600, lineHeight: 1.15 }}>
            {show(referenceQuery(log, attr, validCursor, systemCursor))}
          </div>
        </div>
      ))}
      <div style={{ marginLeft: 'auto', fontSize: 13, color: 'var(--ink-soft)', textAlign: 'right' }}>
        valid {formatDayLong(validCursor)}
        <br />
        as recorded on {formatDayLong(systemCursor)}
      </div>
    </div>
  )
}

import { toDate } from '../core/dates'
import type { Day } from '../core/types'

/** Maps a day onto a pixel position. The only arithmetic the drawings share. */
export type Scale = (d: Day) => number

export function linear(domain: [Day, Day], range: [number, number]): Scale {
  const [d0, d1] = domain
  const [r0, r1] = range
  const span = d1 - d0 || 1
  return (d) => r0 + ((d - d0) / span) * (r1 - r0)
}

export function invert(domain: [Day, Day], range: [number, number]): (px: number) => Day {
  const [d0, d1] = domain
  const [r0, r1] = range
  const span = r1 - r0 || 1
  return (px) => Math.round(d0 + ((px - r0) / span) * (d1 - d0))
}

/**
 * Month boundaries inside the window. Months rather than evenly spaced ticks,
 * because every label in this interface is a date and the eye is looking for
 * "which month", not "how many days in".
 */
export function monthTicks(start: Day, end: Day): Day[] {
  const ticks: Day[] = []
  const from = toDate(start)
  let year = from.getUTCFullYear()
  let month = from.getUTCMonth()
  // Start at the first boundary at or after `start`.
  if (from.getUTCDate() > 1) month += 1

  for (;;) {
    const d = Date.UTC(year, month, 1)
    const asDay = Math.round((d - toDate(start).getTime()) / 86_400_000) + start
    if (asDay > end) break
    if (asDay >= start) ticks.push(asDay)
    month += 1
    if (month > 11) { month = 0; year += 1 }
  }
  return ticks
}

import type { Value } from '../core/types'

/**
 * Colour is assigned by the job it does, and the categorical set is validated
 * rather than chosen by eye: these three hues clear every all-pairs gate on a
 * light surface (worst colour-vision-deficient separation 9.2, worst
 * normal-vision 24.0). Three is the cap for all-pairs work — a fourth slot puts
 * yellow beside orange and fails — which is why the generated histories draw
 * from three managers.
 *
 * Aqua sits below 3:1 against the surface, so the relief rule applies: every
 * region on the plane carries a visible label, and colour never has to be read
 * on its own.
 */
export const CATEGORICAL = ['#2a78d6', '#eb6834', '#1baf7a'] as const

/** Single hue, light to dark — magnitude, not identity. */
export const SEQUENTIAL = [
  '#cde2fb', '#b7d3f6', '#9ec5f4', '#86b6ef', '#6da7ec', '#5598e7',
  '#3987e5', '#2a78d6', '#256abf', '#1c5cab', '#184f95', '#104281', '#0d366b',
] as const

export const NO_VALUE = '#f3f2ef'

/**
 * Colour follows the entity, never its rank in the current view. Both scales
 * are built from the whole log, so dragging a cursor never repaints a value
 * that did not change — which would read as data changing when only the
 * viewport did.
 */
export type ValueColours = (value: Value | undefined) => string

export function coloursFor(allValues: readonly Value[]): ValueColours {
  const numbers = allValues.filter((v): v is number => typeof v === 'number')
  const strings = [...new Set(allValues.filter((v): v is string => typeof v === 'string'))].sort()

  const lo = Math.min(...numbers)
  const hi = Math.max(...numbers)

  return (value) => {
    if (value === undefined) return NO_VALUE
    if (typeof value === 'number') {
      if (numbers.length === 0) return SEQUENTIAL[6]!
      const t = hi === lo ? 0.5 : (value - lo) / (hi - lo)
      const i = Math.round(t * (SEQUENTIAL.length - 1))
      return SEQUENTIAL[Math.min(SEQUENTIAL.length - 1, Math.max(0, i))]!
    }
    const i = strings.indexOf(value)
    // Past the validated three, fall back to ink rather than inventing a hue.
    return i >= 0 && i < CATEGORICAL.length ? CATEGORICAL[i]! : '#55534e'
  }
}

/** Dark fills need light text. Rough luminance is enough for this decision. */
export function inkOn(hex: string): string {
  const n = parseInt(hex.slice(1), 16)
  const [r, g, b] = [(n >> 16) & 255, (n >> 8) & 255, n & 255]
  const lum = (0.299 * r! + 0.587 * g! + 0.114 * b!) / 255
  return lum > 0.6 ? '#1a1a19' : '#ffffff'
}

/**
 * Line-series hues for the cost curves, in fixed slot order. Validated on the
 * adjacent pairlist that line charts use: worst colour-vision-deficient
 * separation 9.1, worst normal-vision 19.6, both clear. Three of the five sit
 * below 3:1 against the surface, so the relief rule applies — every line
 * carries a direct label at its right end and the panel ships a table view.
 *
 * Keyed by strategy rather than by position in the current chart, so hiding a
 * series never repaints the ones that remain.
 */
export const SERIES: Record<string, string> = {
  deltas: '#2a78d6',
  intervals: '#eb6834',
  snapshots: '#1baf7a',
  hybrid: '#eda100',
  snapshotStale: '#e87ba4',
}

export const seriesColour = (key: string): string => SERIES[key] ?? '#55534e'

import { renderToStaticMarkup } from 'react-dom/server'
import { describe, expect, it } from 'vitest'
import { day } from '../core/dates'
import { HORIZON, SCENARIO } from '../core/log'
import { App } from './App'
import { TwinTimelines } from './TwinTimelines'

/**
 * A static render will not catch a layout problem, but it does catch the
 * failures that are expensive to find by eye: a component that throws on real
 * data, geometry that produces NaN in an attribute, or a region that silently
 * renders nothing.
 */
const noNaN = (markup: string) => {
  expect(markup).not.toMatch(/NaN/)
  expect(markup).not.toMatch(/Infinity/)
}

describe('the app renders', () => {
  it('without throwing, on the scenario', () => {
    const markup = renderToStaticMarkup(<App />)
    expect(markup).toContain('Chronoscope')
    noNaN(markup)
  })

  it('showing both attributes at the opening coordinates, not one', () => {
    // 1 May valid, clock at 10 June: the backdated raise is recorded by then.
    const markup = renderToStaticMarkup(<App />)
    expect(markup).toContain('72,000')
    expect(markup).toContain('Rob')
  })

  it('with the two axes as the only controls', () => {
    const markup = renderToStaticMarkup(<App />)
    expect(markup).toContain('valid time')
    expect(markup).toContain('system time')
    expect(markup).not.toContain('<input')
  })
})

describe('the timelines render', () => {
  it('one connector and two dots per fact', () => {
    const markup = renderToStaticMarkup(
      <TwinTimelines log={SCENARIO} horizon={HORIZON} clock={day(2026, 6, 10)}
                     validCursor={day(2026, 5, 1)} systemCursor={day(2026, 6, 10)}
                     onValid={() => {}} onSystem={() => {}} />,
    )
    expect(markup.match(/<circle/g)).toHaveLength(SCENARIO.length * 2)
    noNaN(markup)
  })

  it('survives an empty log', () => {
    noNaN(renderToStaticMarkup(
      <TwinTimelines log={[]} horizon={HORIZON} clock={HORIZON.start}
                     validCursor={HORIZON.start} systemCursor={HORIZON.start}
                     onValid={() => {}} onSystem={() => {}} />,
    ))
  })
})

